from textlesson import build
S=dict(cls=6,subj="science",subj_file="science")
build(dict(S,ch="exploring-magnets",topic="magnetic-and-non-magnetic",name_en="Magnetic and non-magnetic things",name_ta="காந்தம் மற்றும் காந்தமில்லாப் பொருட்கள்",
 objectives=["Sort things into magnetic and non-magnetic","Say what happens when like poles meet"],
 story=("Asha and the lost pin","Asha dropped a steel pin in a heap of sand. She could not see it.\nHer grandfather brought a small bar magnet and moved it over the sand.\nThe pin jumped up and stuck to the magnet! Asha laughed. \"The magnet found it for me!\""),
 explain=["A magnet attracts some things. Things that a magnet attracts are called magnetic. Iron, steel, nickel and cobalt are magnetic.","Things that a magnet does not attract are non-magnetic. Plastic, wood, paper, glass, rubber and copper are non-magnetic.","Every magnet has two ends called poles: the north pole and the south pole. The pull is strongest at the poles.","Unlike poles attract each other (north and south). Like poles repel each other (north and north, or south and south).","A freely hanging bar magnet turns and rests in the north-south direction. A compass works in this way."],
 terms=["magnet","magnetic","pole","attract","repel"],
 narr=[("A magnet pulls some things towards it. We say it attracts them. Iron and steel are attracted.","iron, steel: magnetic"),("Plastic, wood, paper and glass are not attracted. They are non-magnetic.","plastic, wood: non-magnetic"),("A magnet has two poles, north and south. Unlike poles attract and like poles push each other away.","N-S attract, N-N repel"),("A bar magnet hanging freely always settles along the north-south direction.","a compass needle")],
 ex=("Ravi has a nail, a coin made of copper, a rubber and a steel spoon. Which ones will a magnet attract?",[("Check what each thing is made of: iron, copper, rubber, steel.","The material decides if it is magnetic."),("Iron and steel are magnetic. Copper and rubber are not.","Only iron, steel, nickel and cobalt are attracted."),("So the magnet attracts the nail and the steel spoon.","The nail is iron and the spoon is steel.")]),
 tb=("A friend says every metal sticks to a magnet. Explain why she is not right.",["Only some metals such as iron, steel, nickel and cobalt are magnetic.","Metals such as copper, aluminium and gold are not attracted by a magnet."],["Thinking all metals are magnetic."]),
 summary=["Magnets attract iron, steel, nickel and cobalt.","Plastic, wood, paper, glass and copper are non-magnetic.","Unlike poles attract; like poles repel.","A hanging bar magnet rests in the north-south direction."],
 q=[("mcq",1,"r1-iron","Which of these will a magnet attract?","an iron nail",[("a plastic comb","Plastic is not magnetic."),("a wooden ruler","Wood is not magnetic.")],"Iron is a magnetic material."),
    ("tf",1,"r1-glass","A magnet attracts a glass marble.",False,"False. Glass is non-magnetic."),
    ("mcq",2,"r2-poles","What are the two ends of a magnet called?","north pole and south pole",[("front pole and back pole","Magnet poles are named north and south."),("left end and right end","Magnet poles are named north and south.")],"Every magnet has a north pole and a south pole."),
    ("tf",2,"r2-like","Two north poles pull each other together.",False,"False. Like poles repel."),
    ("mcq",3,"r3-unlike","What happens when the north pole of one magnet comes near the south pole of another?","they attract",[("they repel","Unlike poles attract."),("nothing happens","Magnets act on each other when poles are close.")],"Unlike poles attract each other."),
    ("short",3,"r3-name","Name one magnetic metal.",["iron","steel","nickel","cobalt"],"Iron, steel, nickel and cobalt are magnetic."),
    ("mcq",4,"r4-copper","Which pair has only non-magnetic things?","copper coin and rubber band",[("iron nail and wood","The iron nail is magnetic."),("steel pin and paper","The steel pin is magnetic.")],"Copper and rubber are non-magnetic."),
    ("tf",4,"r4-direction","A freely hanging bar magnet settles in the north-south direction.",True,"True. This is how a compass works.")]))
build(dict(S,ch="a-journey-through-states-of-water",topic="ice-water-and-vapour",name_en="Ice, water and vapour",name_ta="ஐஸ், தண்ணீர், நீராவி",
 objectives=["Name the three states of water","Explain melting, freezing, evaporation and condensation"],
 story=("The puddle that vanished","After the rain, a puddle lay in front of Kabir's house. By afternoon it was gone.\n\"Where did the water go?\" he asked his mother.\n\"The warm sun turned it into vapour, and the vapour went into the air,\" she said."),
 explain=["Water exists in three states: solid (ice), liquid (water) and gas (water vapour).","When ice is heated it melts and becomes water. This is melting. When water is cooled enough it freezes into ice. This is freezing.","When water is heated it changes to water vapour. This is evaporation. It happens slowly even without boiling, and faster when it is hot, dry and windy.","When water vapour cools it changes back to tiny drops of water. This is condensation. Drops on the outside of a cold glass are condensed water vapour from the air.","Clouds, rain, rivers and the sea are linked in the water cycle."],
 terms=["solid","liquid","vapour","melting","freezing","evaporation","condensation"],
 narr=[("Water has three states: solid ice, liquid water, and gas called vapour.","ice - water - vapour"),("Heat ice and it melts into water. Cool water enough and it freezes into ice.","melting / freezing"),("Warm water slowly turns into vapour. This is evaporation. Clothes dry in the sun because of it.","evaporation"),("Cool vapour turns into tiny water drops. This is condensation. Look at a cold glass of water.","condensation")],
 ex=("Wet clothes dry faster on a hot, windy day than on a cool, still day. Why?",[("Wet clothes dry because the water in them evaporates.","Drying means water changing to vapour."),("Heat and wind help evaporation happen faster.","Warm air gives energy and wind carries the vapour away."),("So clothes dry faster on a hot, windy day.","More evaporation means faster drying.")]),
 tb=("A glass of cold water has drops on its outside. Where did these drops come from?",["Water vapour in the air touched the cold glass.","It cooled and condensed into water drops."],["Thinking the water leaked through the glass."]),
 summary=["Water can be solid, liquid or gas.","Melting: ice to water. Freezing: water to ice.","Evaporation: water to vapour. Condensation: vapour to water."],
 q=[("mcq",1,"r1-solid","Which is the solid state of water?","ice",[("steam","Steam is water vapour, a gas."),("dew","Dew is liquid water.")],"Ice is solid water."),
    ("tf",1,"r1-vapour","Water vapour is a gas.",True,"True. It is water in gas form."),
    ("mcq",2,"r2-melt","What is the change of ice into water called?","melting",[("freezing","Freezing is water becoming ice."),("evaporation","Evaporation is water becoming vapour.")],"Ice becomes water by melting."),
    ("tf",2,"r2-boil","Water must boil before it can evaporate.",False,"False. Water evaporates slowly at any temperature."),
    ("mcq",3,"r3-cond","Drops form on the outside of a cold glass. This is because of","condensation",[("evaporation","The drops come from vapour turning to water."),("melting","Nothing in the glass is melting.")],"Vapour in the air cools and condenses."),
    ("short",3,"r3-dry","Name one thing that makes wet clothes dry faster.",["sun","heat","wind","hot","warm","air"],"Heat and wind speed up evaporation."),
    ("mcq",4,"r4-freeze","Water is kept in a freezer and turns to ice. This change is","freezing",[("melting","Melting is the opposite change."),("condensation","Condensation is vapour to water.")],"Cooling water until it becomes solid is freezing."),
    ("tf",4,"r4-puddle","A puddle disappears mostly because its water evaporates.",True,"True. The water turns into vapour and goes into the air.")]))
build(dict(S,ch="beyond-earth",topic="sun-earth-and-moon",name_en="The Sun, Earth and Moon",name_ta="சூரியன், பூமி, நிலா",
 objectives=["Say what rotation and revolution of the Earth cause","Explain the phases of the Moon"],
 story=("Why does the Moon change shape?","Tara watched the Moon every night for a week. On Monday it was a thin curve. By Sunday it was almost round.\n\"Is someone cutting the Moon?\" she asked her uncle.\n\"No,\" he smiled. \"The Moon is always round. We see more or less of its lit half as it moves around the Earth.\""),
 explain=["The Sun is a star. It gives us light and heat. The Earth and the Moon do not make their own light.","The Earth spins on its axis once in about 24 hours. This is rotation. It gives us day and night.","The Earth moves around the Sun once in about 365 days. This is revolution. One revolution is one year.","The Moon moves around the Earth once in about 27 days. The Moon shines because it reflects sunlight.","We see different amounts of the lit half of the Moon on different days. These are the phases of the Moon, from new moon to full moon."],
 terms=["rotation","revolution","axis","phases","new moon","full moon"],
 narr=[("The Sun is a star. It gives light and heat. The Moon only reflects sunlight.","Sun: star, Moon: reflects"),("The Earth spins on its axis once in about twenty-four hours. This rotation gives day and night.","rotation: day and night"),("The Earth goes around the Sun once in about three hundred and sixty-five days. This revolution makes a year.","revolution: one year"),("The Moon goes around the Earth. We see its lit part change shape. These are the phases.","phases of the Moon")],
 ex=("How many days does the Earth take to go once around the Sun, and what do we call this time?",[("The Earth moves around the Sun. This movement is called revolution.","Going around another body is revolution."),("One revolution takes about 365 days.","This is the length of a year."),("So the answer is about 365 days, which is one year.","One year is one revolution.")]),
 tb=("Your younger brother asks why we have day and night. What will you tell him?",["The Earth spins on its axis once in about 24 hours.","The side facing the Sun has day and the other side has night."],["Thinking the Sun moves around the Earth to make day and night."]),
 summary=["Rotation of the Earth gives day and night.","Revolution of the Earth around the Sun takes a year.","The Moon reflects sunlight and goes around the Earth.","Phases are the changing shapes of the lit Moon."],
 q=[("mcq",1,"r1-star","Which one gives its own light?","the Sun",[("the Moon","The Moon only reflects sunlight."),("the Earth","The Earth does not make light.")],"The Sun is a star and makes its own light."),
    ("tf",1,"r1-round","The Earth spins on its axis.",True,"True. This is called rotation."),
    ("mcq",2,"r2-daynight","What gives us day and night?","rotation of the Earth",[("revolution of the Earth","Revolution gives the year."),("phases of the Moon","Phases show the Moon's changing look.")],"The spinning Earth turns each side toward and away from the Sun."),
    ("tf",2,"r2-year","The Earth takes about 365 days to go around the Sun.",True,"True. This is one year."),
    ("mcq",3,"r3-moon","Why does the Moon shine?","it reflects sunlight",[("it makes its own light","The Moon does not make light."),("it is on fire","The Moon is not burning.")],"The Moon reflects the Sun's light."),
    ("short",3,"r3-phase","What do we call the changing shapes of the Moon?",["phases","phases of the moon","phase"],"They are the phases of the Moon."),
    ("mcq",4,"r4-full","On a full moon day we see","the whole lit half of the Moon",[("none of the Moon","That is a new moon."),("a thin curve","That is a crescent.")],"On full moon day the whole lit face points towards us."),
    ("tf",4,"r4-cut","The Moon really changes its shape every night.",False,"False. The Moon is always round; we see different amounts of its lit part.")]))
build(dict(S,ch="measurement-of-length-and-motion",topic="measuring-length",name_en="Measuring length",name_ta="நீளத்தை அளத்தல்",
 objectives=["Say why standard units are needed","Measure length correctly with a ruler"],
 story=("Whose hand span?","Rani measured the table with her hand span and got 8. Her father measured it and got 6.\n\"Why do we get different answers?\" she asked.\n\"Our hands are different sizes,\" said her father. \"That is why we need the same unit for everyone.\""),
 explain=["To measure means to compare with a fixed unit. Hand spans, feet and steps give different answers for different people.","So all over the world we use standard units. The SI unit of length is the metre (m).","Shorter lengths are in centimetres (cm) and millimetres (mm); longer distances are in kilometres (km). 1 m = 100 cm, 1 cm = 10 mm and 1 km = 1000 m.","To measure with a ruler: place the zero mark at one end, keep the ruler straight along the length, and read from straight above the other end.","A measuring tape is used for curved or long things. A thread can measure a curved line: lay it along the line, then straighten it and measure."],
 terms=["metre","centimetre","millimetre","kilometre","ruler","SI unit"],
 narr=[("Hand spans and steps give different answers for different people, so we need standard units.","need standard units"),("The standard unit of length is the metre. A small length is in centimetres or millimetres.","m, cm, mm, km"),("One metre is one hundred centimetres. One centimetre is ten millimetres. One kilometre is one thousand metres.","1 m = 100 cm"),("Put the zero mark at one end, keep the ruler straight, and read from straight above.","zero at the start")],
 ex=("A pencil is 15 cm long. How many millimetres is that?",[("We know that 1 cm is 10 mm.","This is the link between the two units."),("So 15 cm is 15 times 10 mm.","Multiply to change a bigger unit to a smaller one."),("15 times 10 is 150, so the pencil is 150 mm.","Check: the answer is a bigger number in the smaller unit.")]),
 tb=("A classmate measures a book with the ruler starting at the 1 cm mark and reads 21 cm at the other end. What is the real length?",["The ruler did not start at zero.","The real length is 21 cm minus 1 cm, which is 20 cm."],["Thinking the last reading is always the length."]),
 summary=["Standard units give the same answer for everyone.","The SI unit of length is the metre.","1 m = 100 cm, 1 cm = 10 mm, 1 km = 1000 m.","Start at zero, keep the ruler straight and read from above."],
 q=[("mcq",1,"r1-unit","What is the SI unit of length?","metre",[("kilogram","Kilogram is a unit of mass."),("litre","Litre is a unit of volume.")],"The SI unit of length is the metre."),
    ("tf",1,"r1-hand","Hand spans give the same length for every person.",False,"False. Hands are different sizes, so we use standard units."),
    ("mcq",2,"r2-cm","How many centimetres are in 1 metre?","100",[("10","10 mm make 1 cm."),("1000","1000 m make 1 km.")],"1 m = 100 cm."),
    ("tf",2,"r2-km","1 kilometre is 1000 metres.",True,"True."),
    ("mcq",3,"r3-mm","A line is 4 cm long. How long is it in mm?","40 mm",[("4 mm","1 cm is 10 mm, so 4 cm is 40 mm."),("400 mm","That is 40 cm.")],"4 cm is 4 times 10 mm = 40 mm."),
    ("short",3,"r3-tool","Name a tool to measure the length of a pencil.",["ruler","scale","measuring tape","tape"],"A ruler or scale measures short lengths."),
    ("mcq",4,"r4-read","Where should your eye be when you read a ruler?","straight above the mark",[("far to the side","That gives a wrong reading."),("below the ruler","That gives a wrong reading.")],"Reading from straight above avoids a wrong value."),
    ("tf",4,"r4-curve","A thread can help measure the length of a curved line.",True,"True. Lay the thread along the curve, straighten it and measure it.")]))
